document.addEventListener('click', e => {
  const el = e.target.closest('[data-act]');
  if (!el) return;
  const raw = el.dataset.act; const i = raw.indexOf(':');
  const name = i < 0 ? raw : raw.slice(0, i), arg = i < 0 ? undefined : raw.slice(i + 1);
  if (el.tagName === 'A') e.preventDefault();
  e.stopPropagation();
  const fn = A[name]; if (fn) fn(arg, el);
})

coreHandlers.tool:
function openTool(id) {
  closeSheet();
  if (id === 'mentor') return setTimeout(() => openMentor(), 250);
  const map = { courses: 'courses', xray: 'xray', mindmap: 'mindmap', notes: 'note:n1', engine: 'engine', tests: 'tests', mains: 'mains', answerbank: 'answerbank', calendar: 'calendar', cloud: 'cloud', querydb: 'querydb' };
  const [v, a] = map[id].split(':');
  push(v, a);
}

coreHandlers.jump:
async x => {
    closeSheet();
    if (['book', 'intro', 'auth', 'verify'].includes(x)) return go(x);
    if (S.stage !== 'app') go('app');
    closeAllPages(true);
    if (['home', 'learn', 'practice', 'current', 'menu', 'profile'].includes(x)) return setTab(x);
    if (x === 'quiz') { setTab('practice'); return startQuiz(true); }
    if (x === 'mains') { setTab('practice'); return push('mains'); }
    if (x === 'mentor') { setTab('home'); return openMentor(); }
    if (x === 'article') { setTab('current'); return push('article', 'c4'); }
    if (x === 'plans') { setTab('profile'); return push('upgrade'); }
    if (x === 'status') { setTab('profile'); return push('status'); }
  }
